                m2=re.match(r'^    name: (.+)$',s)
                if m2 and jname is None: jname=(j+1,m2.group(1))
                if tm and job: break
            print(f, 'fetch@', i+1, '| job:', job, '| name:', jname, '| timeout:', tm)
EOF

