      'testflight': (
        '.github/workflows/build-mobile.yml',
        {'build-android', 'submit-android'},
        {},
        220,
        14400,
        360,
      ),
      'play': (
        '.github/workflows/build-mobile.yml',
        {'build-ios', 'submit-ios'},
        {},
        85,
        6600,
        240,
      ),
      'cli': (
        '.github/workflows/build-macos.yml',
        {},
        {'build-macos': 2},
        325,
        20400,
        360,
      ),
      'website': ('.github/workflows/pages.yml', {}, {}, 60, 4500, 180),
      'addin': (
        '.github/workflows/office-addin.yml',
        {},
        {},
        45,
        3600,
        150,
      ),
    };

