// Issues #343 + #344 — nightly release orchestration:
//
// #343: the daily-publish Play/TestFlight legs dispatch the SAME workflow
// (build-mobile.yml) as concurrent `needs: plan` siblings and identified
// "their" run by event + a 60s createdAt window only, taking [0] of the
// list — so the Play leg could latch the TestFlight run (or a stale
// same-shaped run from the trailing window) and watch a build that never
// builds Android. The fix: children carry a run-name embedding their
// inputs, and the watcher correlates by exact displayTitle + NEWEST match
// + a tight window.
//
// #344: a self-hosted runner that lost its final job-completion report
// holds a SUCCEEDED job in_progress forever (nothing server-side detects
// a stale self-hosted job below the workflow timeout), blocking the
// single-runner pool and every watcher for the full 300m leg timeout. The
// fix: job-level timeout-minutes on the self-hosted build-mobile jobs, and
// a budgeted watch in the shared dispatcher that cancels a wedged run and
// re-dispatches exactly once before failing.
//
// #351 (timeout arithmetic recompute): the original budgets sat BELOW the
// children's ceilings — the watcher cancelled legitimate slow children
// (testflight 90m budget vs a 220m chain whose submit-ios alone can spend
// 90m waiting for Apple processing + 15m verifying distribution), and the
// website/addin budgets could never even complete their cancel +
// re-dispatch inside the 45m leg timeout (dead self-heal). Now: every job
// in a watched child chain carries an explicit timeout-minutes; child
// worst-case = sum along the serialized critical path; budget =
// worst-case + ~15m margin; leg timeout > budget, and ≥ 2×budget + margin
// whenever that fits under GitHub's 360m job cap so the second-wedge
// fail-fast can actually fire inside the leg.
//
// Structural lint over the workflow YAML plus behavioral tests of
// scripts/dispatch_and_watch.sh against a stubbed `gh` (same style as
// release_hygiene_test.dart). The stub pipes fixtures through the REAL jq
// expression the script passes to `gh run list`, so the correlation logic
// itself (title filter, window, newest-match) is under test.
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();
YamlMap jobsOf(String workflowPath) =>
    loadYaml(read(workflowPath))['jobs'] as YamlMap;

// ── stubbed gh ─────────────────────────────────────────────────────────────

final _fixtureRoot = Directory.systemTemp.createTempSync('dispatch-watch-');

/// ISO-8601 seconds-resolution timestamp (GitHub `createdAt` shape) offset
/// from now by [seconds].
String iso(int seconds) {
  final utc = DateTime.now()
      .toUtc()
      .add(Duration(seconds: seconds))
      .toIso8601String();
  return '${utc.substring(0, 19)}Z';
}

/// Installs a stub `gh` that logs every invocation and answers from canned
/// files in [dir]:
///   `runs.json`        — raw `gh run list --json` array
///   `view-<id>.txt`    — one `<status> <conclusion>` line per
///                        `gh run view <id>` poll; the last line repeats
///                        once exhausted
///   `cancelled-<id>`   — marker created by `gh run cancel`
///   `list-calls`       — internal counter
/// GH_STUB_LIST_EMPTY_FIRST=N makes the first N `run list` calls return [].
/// Any `--jq` argument is applied with the real jq, so the script's own
/// correlation expressions run against the fixtures.
String stubGh(String dir) {
  final bin = Directory('$dir/bin')..createSync(recursive: true);
  File('${bin.path}/gh').writeAsStringSync('''
#!/usr/bin/env bash
echo "\$*" >> "\$GH_LOG_FILE"
cmd="\$1"; sub="\$2"

jq_arg=""
args=("\$@")
for ((i=0; i<\$#; i++)); do
  if [ "\${args[\$i]}" = "--jq" ]; then jq_arg="\${args[\$((i+1))]}"; fi
done

apply_jq() {
  if [ -n "\$jq_arg" ]; then jq -r "\$jq_arg"; else cat; fi
}

case "\$cmd" in
  workflow) : ;;
  run)
    case "\$sub" in
      list)
        calls=\$(( \$(cat "\$GH_STUB_DIR/list-calls" 2>/dev/null || echo 0) + 1 ))
        echo "\$calls" > "\$GH_STUB_DIR/list-calls"
        runs_file="\$GH_STUB_DIR/runs.json"
        # Once a run has been cancelled, prefer runs2.json when present:
        # models the re-dispatched run appearing only after the cancel.
        if ls "\$GH_STUB_DIR"/cancelled-* >/dev/null 2>&1 && [ -f "\$GH_STUB_DIR/runs2.json" ]; then
          runs_file="\$GH_STUB_DIR/runs2.json"
        fi
        if [ "\$calls" -le "\${GH_STUB_LIST_EMPTY_FIRST:-0}" ]; then
          printf '[]' | apply_jq
        else
          cat "\$runs_file" | apply_jq
        fi
        ;;
      view)
        id="\$3"
        if [ -f "\$GH_STUB_DIR/cancelled-\$id" ]; then
          status=completed; conclusion=cancelled
        else
          f="\$GH_STUB_DIR/view-\$id.txt"
          line=\$(head -1 "\$f")
          sed -i.bak '1d' "\$f" && rm -f "\$f.bak"
          if ! [ -s "\$f" ]; then printf '%s\\n' "\$line" > "\$f"; fi
          status="\${line%% *}"; conclusion="\${line#* }"
        fi
        printf '{"status":"%s","conclusion":"%s"}' "\$status" "\$conclusion" | apply_jq

{"content":"// gh-1477 — the `Derive version` job in build-mobile.yml ran
// actions/checkout with `fetch-depth: 0` (full history + every tag + every
// blob ever written) under `timeout-minutes: 10`. The repo gains a release
// tag + commits daily, so the full fetch only got slower until, on
// 2026-10-10, it outgrew the ceiling: the job was killed exactly 600s in,
// mid-`git fetch`, and the whole TestFlight leg of the daily train
// collapsed to `cancelled` (run 38027695551, issue #1472). A time bomb,
// not a flake — and the twin `Derive version` job in build-macos.yml, the
// daily-publish `plan` job, and a family of ci.yml guard jobs carried the
// same shape.
//
// Deliberately text/YAML-level asserts (the issue's "workflow-shape test"
// never-again, same static-assert pattern as
// nightly_desktop_leg_guard_test.dart / store_automation_guard_test.dart):
//  AC1  every checkout step that asks for full history
//       (`fetch-depth: 0`) must pair it with `filter: blob:none` — the
//       jobs read tags / commit metadata / `git log` ranges, never
//       historical file contents, and a blobless clone skips transferring
//       every blob ever written while git still lazy-fetches the rare
//       blob something actually asks for,
//  AC2  the metadata-only daily-train jobs (derive version ×2, daily
//       plan) whose ONLY pre-timeout work is that fetch must carry a ≥20m
//       ceiling — the 10m seatbelt was the bomb's detonator.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

/// Every checkout step (`uses: actions/checkout…`) across all workflow
/// jobs, as (workflow, jobId, stepIndex, step).
Iterable<(String, String, int, YamlMap)> checkoutSteps(String workflowPath) {
  final jobs = loadYaml(read(workflowPath))['jobs'] as YamlMap;
  final out = <(String, String, int, YamlMap)>[];
  for (final entry in jobs.entries) {
    final steps = (entry.value as YamlMap)['steps'];
    if (steps is! YamlList) continue;
    for (var i = 0; i < steps.length; i++) {
      final step = steps[i];
      if (step is! YamlMap) continue;
      final uses = step['uses']?.toString() ?? '';
      if (uses.startsWith('actions/checkout@')) {
        out.add((workflowPath, entry.key as String, i, step));
      }
    }
  }
  return out;
}

bool asksFullHistory(YamlMap step) {
  final depth = (step['with'] as YamlMap?)?['fetch-depth'];
  return depth == 0 || depth == '0';
}

void main() {
  final workflows = Directory('.github/workflows')
      .listSync()
      .whereType<File>()
      .where((f) => f.path.endsWith('.yml'))
      .map((f) => f.path)
      .toList()
    ..sort();

  group('AC1 — full-history checkouts are blobless (gh-1477)', () {
    for (final workflow in workflows) {
      test(workflow, () {
        for (final (path, jobId, stepIndex, step)
            in checkoutSteps(workflow)) {
          if (!asksFullHistory(step)) continue;
          final filter = (step['with'] as YamlMap?)?['filter'];
          expect(
            filter,
            'blob:none',
            reason:
                '$path job "$jobId" step $stepIndex pairs `fetch-depth: 0` '
                'with NO `filter: blob:none` — a full clone transfers every '
                'blob ever written and grows daily (gh-1477: the fetch '
                'outgrew its own 10m job timeout and cancelled the daily '
                'TestFlight leg, run 38027695551). The job reads tags / '
                'commit metadata only; blobs are waste.',
          );
        }
      });
    }
  });

  group('AC2 — metadata-only daily-train jobs carry a ≥20m seatbelt', () {
    const metadataOnlyJobs = <String, List<String>>{
      // (workflow, jobId) — the job's only pre-timeout work is a tags/
      // metadata fetch; a cancelled job collapses the whole daily train.
      '.github/workflows/build-mobile.yml': ['version'],
      '.github/workflows/build-macos.yml': ['version'],
      '.github/workflows/daily-publish.yml': ['plan'],
    };
    for (final entry in metadataOnlyJobs.entries) {
      for (final jobId in entry.value) {
        test('${entry.key} job "$jobId"', () {
          final job =
              (loadYaml(read(entry.key))['jobs'] as YamlMap)[jobId]
                  as YamlMap;
          final timeout = job['timeout-minutes'];
          expect(
            timeout,
            isNotNull,
            reason:
                '${entry.key} job "$jobId" lost its explicit ceiling — the '
                '#351 watch-budget arithmetic needs one',
          );
          expect(
            (timeout as num) >= 20,
            isTrue,
            reason:
                '${entry.key} job "$jobId" runs a full-history fetch under '
                'only ${timeout}m — the exact gh-1477 bomb (fetch outgrew '
                'the ceiling → job cancelled → daily leg collapsed). '
                '≥20m is the seatbelt; the blobless filter (AC1) makes the '
                'fetch itself cheap.',
          );
        });
      }
    }
  });
}
